    console.log(`\nTotal calls: ${calls}`);
    if (calls === 1) {
        console.log('SUCCESS: Debounce worked correctly - only the last call was processed after the wait period');
    } else {
        console.log('FAILURE: Expected 1 call, got', calls);
    }
}, 150);
